import React, { useState, useEffect } from 'react';
import { useNavigate, useLocation } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';

const Header = ({ balance, setBalance, notifications }) => {
  const { user, logout } = useAuth();
  const [showUserMenu, setShowUserMenu] = useState(false);
  const [showNotifications, setShowNotifications] = useState(false);
  const [showWalletModal, setShowWalletModal] = useState(false);
  const [localNotifications, setLocalNotifications] = useState(notifications || []);
  const navigate = useNavigate();
  const location = useLocation();

  useEffect(() => {
    setLocalNotifications(notifications || []);
  }, [notifications]);

  const handleLogout = () => {
    logout();
    navigate('/login');
    setShowUserMenu(false);
  };

  const handleNotificationClick = (notification) => {
    if (notification.link) {
      navigate(notification.link);
    }
    setShowNotifications(false);
  };

  const getGreeting = () => {
    const hour = new Date().getHours();
    if (hour < 12) return 'Good Morning';
    if (hour < 18) return 'Good Afternoon';
    return 'Good Evening';
  };

  const getActivePageTitle = () => {
    const path = location.pathname;
    switch(path) {
      case '/coinflip': return 'Coin Flip';
      case '/blackjack': return 'Blackjack';
      case '/wallet': return 'Wallet';
      case '/stats': return 'Statistics';
      case '/provably-fair': return 'Provably Fair';
      case '/profile': return 'Profile';
      case '/admin': return 'Admin Panel';
      default: return 'Dashboard';
    }
  };

  // Calculate total inventory value
  const calculateInventoryValue = () => {
    // This would come from the user's inventory in a real app
    // For now, returning a mock value
    return 1500; // Example total inventory value
  };

  const totalInventoryValue = calculateInventoryValue();

  return (
    <header className="header">
      <div className="header-left">
        <h1 className="page-title">{getActivePageTitle()}</h1>
      </div>

      <div className="header-center">
        <div className="balance-display">
          <span className="balance-label">Balance:</span>
          <span className="balance-amount">{balance?.toFixed(2) || '0.00'} AMP</span>
        </div>
        <div className="balance-display">
          <span className="balance-label">Inventory Value:</span>
          <span className="balance-amount">{totalInventoryValue} AMP</span>
        </div>
      </div>

      <div className="header-right">
        <div className="header-controls">
          {/* Wallet Button */}
          <button 
            className="wallet-btn"
            onClick={() => setShowWalletModal(true)}
          >
            💰 Wallet
          </button>

          {/* Notifications */}
          <div className="notification-dropdown">
            <button 
              className="notification-btn"
              onClick={() => setShowNotifications(!showNotifications)}
            >
              🔔
              {localNotifications.length > 0 && (
                <span className="notification-badge">{localNotifications.length}</span>
              )}
            </button>

            {showNotifications && (
              <div className="notification-dropdown-menu">
                {localNotifications.length > 0 ? (
                  localNotifications.map((notification, index) => (
                    <div 
                      key={index} 
                      className="notification-item"
                      onClick={() => handleNotificationClick(notification)}
                    >
                      <div className="notification-content">
                        <strong>{notification.title}</strong>
                        <p>{notification.message}</p>
                        <small>{new Date(notification.timestamp).toLocaleString()}</small>
                      </div>
                    </div>
                  ))
                ) : (
                  <div className="notification-item empty">
                    <p>No new notifications</p>
                  </div>
                )}
              </div>
            )}
          </div>

          {/* User Menu */}
          <div className="user-dropdown">
            <button 
              className="user-btn"
              onClick={() => setShowUserMenu(!showUserMenu)}
            >
              <span className="user-name">{user?.displayName || user?.robloxUsername || 'User'}</span>
              <span className="user-avatar">👤</span>
            </button>

            {showUserMenu && (
              <div className="user-dropdown-menu">
                <div className="user-info">
                  <div className="user-greeting">
                    {getGreeting()}, {user?.displayName || user?.robloxUsername}!
                  </div>
                  <div className="user-stats">
                    <div className="stat-item">
                      <span className="stat-label">Balance:</span>
                      <span className="stat-value">{balance?.toFixed(2) || '0.00'} AMP</span>
                    </div>
                    <div className="stat-item">
                      <span className="stat-label">Inventory Value:</span>
                      <span className="stat-value">{totalInventoryValue} AMP</span>
                    </div>
                    <div className="stat-item">
                      <span className="stat-label">Rank:</span>
                      <span className="stat-value">#{Math.floor(Math.random() * 1000) + 1}</span>
                    </div>
                  </div>
                </div>

                <div className="dropdown-divider"></div>

                <button 
                  className="dropdown-item"
                  onClick={() => {
                    navigate('/profile');
                    setShowUserMenu(false);
                  }}
                >
                  👤 Profile
                </button>

                {user?.isAdmin && (
                  <button 
                    className="dropdown-item"
                    onClick={() => {
                      navigate('/admin');
                      setShowUserMenu(false);
                    }}
                  >
                    ⚙️ Admin Panel
                  </button>
                )}

                <button 
                  className="dropdown-item"
                  onClick={() => {
                    setShowWalletModal(true);
                    setShowUserMenu(false);
                  }}
                >
                  💰 Wallet
                </button>

                <div className="dropdown-divider"></div>

                <button 
                  className="dropdown-item logout-btn"
                  onClick={handleLogout}
                >
                  🚪 Logout
                </button>
              </div>
            )}
          </div>
        </div>
      </div>

      {/* Wallet Modal */}
      {showWalletModal && (
        <div className="wallet-modal-overlay" onClick={() => setShowWalletModal(false)}>
          <div className="wallet-modal" onClick={(e) => e.stopPropagation()}>
            {/* Modal header with close button */}
            <div className="wallet-modal-header">
              <h2>Wallet & Inventory</h2>
              <div className="wallet-actions">
                <button 
                  className="modal-close-btn"
                  onClick={() => setShowWalletModal(false)}
                >
                  ×
                </button>
              </div>
            </div>

            {/* Modal content */}
            <div className="wallet-modal-content">
              {/* Inventory Section */}
              <div className="inventory-section">
                <h3>Your Items (Total Value: {totalInventoryValue} AMP)</h3>
                <div className="inventory-grid">
                  {[1, 2, 3, 4].map((item) => (
                    <div key={item} className="inventory-item">
                      <div className="item-image">
                        <div className="default-item-icon">💎</div>
                      </div>
                      <div className="item-details">
                        <h4>Item {item}</h4>
                        <p className="item-value">250 AMP</p>
                        <span className="badge badge-rare">Rare</span>
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            </div>
          </div>
        </div>
      )}
    </header>
  );
};

export default Header;
